// === 🖼️ VIEW BASE64 IMAGE ===
const item = items[0].json;
const base64String = item.base64_img_string;

if (!base64String) {
    throw new Error("No image data found. The Artist agent likely failed to parse the output.");
}

// Default to png, but use dynamic type if available
const mime = item.base64_img_string_mime || "image/png";
const ext = mime.split('/')[1] || "png";

return [{
    json: item, 
    binary: {
        data: {
            data: base64String,
            mimeType: mime,
            fileExtension: ext,
            fileName: `generated_image.${ext}`
        }
    }
}];

// 1. Grab the ADK envelope
const {
  config,
  session_state: sessionState = {},
  session_events: sessionEvents = []
} = items[0].json;

// 2. Normalize the booleans (parsed fields live in session_state now)
const hasMath = sessionState.math_found === true;
const hasVisual = sessionState.image_request_found === true;

// 3. The Decision Logic — payload formatting (problem/description/status) is
//    handled by the per-branch no_model format_* tasks, so we ONLY pick a route.
let validation_route = "neither";
if (hasMath && hasVisual) validation_route = "ready";
else if (hasMath) validation_route = "math_only";
else if (hasVisual) validation_route = "visual_only";

// 4. Envelope through untouched; validation_route rides at top level for the Switch.
return [{
  json: {
    validation_route,
    config,
    session_state: sessionState,
    session_events: sessionEvents
  }
}];

// =============================================================================
// 📦 FINAL BROADCAST CONTRACT — the completion payload for the GUI stack.
// "Phase 6 - Output" now carries ONLY { config, session_state, session_events };
// everything else is assembled HERE from direct node references. This node is
// the single source of truth for what ships on completion.
//
// DELIVERABLES (12) and who consumes them:
//   ritel-state-manager/main.py (/update-state → Firestore + GCS bucket):
//    1. job_id                              REQUIRED — Firestore doc key
//    2. status: "completed"                 routes images to final paths, uploads
//                                           scaffolding, deletes {job_id}/latest.png
//    3. base64_img_string (+ 4. _mime)      final render → {job_id}/final_illustration.png
//    5. scaffolding_base64_img_string       base diagram → {job_id}/scaffolding.png
//       (+ 6. _mime)
//    7. history                             → {job_id}/history.json  (wire name is
//                                           "history", value is session_events —
//                                           frontend reads state["history"] too)
//   ritel-frontend/app.py:
//    8. user_message                        chat panel (st.info)
//    9. archival_report                     zip download: archival_report.txt
//   10. latest_description                  metadata panel
//   11. original_query                      metadata panel
//   12. total_cost                          metadata panel (sum of session_events[].cost)
//   (+ generation_successful, timestamp, and the "-" phase/agent/task markers,
//    which the frontend shows as generic metadata / completion state)
//
// ⚠️ NEVER include `config` (contains api_keys) or api keys in the payload —
//    the listener merges the entire payload into the Firestore job doc.
// ⚠️ $('Prepare for Vision') exists only on scaffolding paths. DIRECT_IMAGE_GEN
//    (currently unwired) would skip it — grab() returns nulls in that case.
// =============================================================================

const { config = {}, session_state: ss = {}, session_events: events = [] } =
    $('Phase 6 - Output').first().json;

// Direct image sources (scaffolding = base diagram, artist = final render)
const grab = (nodeName) => {
    try {
        const j = $(nodeName).first().json;
        return { img: j.base64_img_string || null, mime: j.base64_img_string_mime || null };
    } catch (e) {
        return { img: null, mime: null }; // node never executed on this path
    }
};
const finalRender = grab('artist - render_final');
const scaffolding = grab('Prepare for Vision');

// === 💸 TOTAL COST — sum of per-event model costs in the transcript ===
const totalCost = Number(
    events.reduce((sum, ev) => sum + (ev.cost || 0), 0).toFixed(6)
);

const finalPayload = {
    job_id: config.job_id,
    status: "completed",
    timestamp: new Date().toISOString(),
    phase_id: "-",
    agent_id: "-",
    task_id: "-",
    total_cost: totalCost,
    base64_img_string: finalRender.img,
    base64_img_string_mime: finalRender.mime || "image/png",
    scaffolding_base64_img_string: scaffolding.img,
    scaffolding_base64_img_string_mime: scaffolding.mime || "image/png",
    history: events,
    user_message: ss.user_message ?? null,
    archival_report: ss.archival_report ?? null,
    generation_successful: ss.generation_successful ?? null,
    latest_description: ss.latest_description ?? null,
    original_query: ss.original_query ?? null
};

// Fire the completion payload to the Cloud Run listener
if (config.enable_gui_logging === true && config.gui_webhook_url) {
    try {
        await this.helpers.httpRequest({
            method: 'POST',
            url: config.gui_webhook_url,
            headers: { 'Content-Type': 'application/json' },
            body: finalPayload,
            json: true,
            timeout: 5000
        });
    } catch (e) {
        console.error("Final broadcast failed:", e.message);
    }
}

return [{ json: {
    status: "Workflow Complete",
    job_id: config.job_id,
    generation_successful: ss.generation_successful ?? null,
    user_message: ss.user_message ?? null,
    latest_description: ss.latest_description ?? null,
    archival_report: ss.archival_report ?? null,
    total_cost: totalCost,
    history: events
} }];

