const input = items[0].json;

let nextTask = "";

switch (true) {
    // Condition 1: Multiple variables evaluated together
    case (input.needs_3d_planning === true && input.needs_arrangement_planning === true):
        nextTask = "inject_both";
        break;

    // Condition 2: Checking a completely different variable or property
    case (input.selected_workflow === "STANDARD_DIAGRAM"):
        nextTask = "standard_setup";
        break;

    // Condition 3: Evaluating length, math, or other logic
    case (input.history && input.history.length > 5):
        nextTask = "deep_history_review";
        break;

    // Fallback if none of the complex conditions are met
    default:
        nextTask = "default_fallback_task"; 
        break;
}

return [{
    json: {
        ...input,
        PHASE_ID: "", // Set target Phase ID here
        AGENT_ID: "", // Set target Agent ID here
        TASK_ID: nextTask
    }
}];

const input = items[0].json;
const state = input.session_state || {};
const lib = input.config.directive_library || {};

// Compose every directive whose planner flag is true in session_state.
// Adding a new constraint type = new schema boolean + new directive_library entry.
const directives = Object.entries(lib)
    .filter(([flag]) => state[flag] === true)
    .map(([, text]) => text);

// inject_constraints is the UNCONDITIONAL stage-3 briefing, and situational_directives
// carries its own leading newlines + header so it concatenates flush onto the end of
// problem_briefing (same idiom as retry_directives in plan_logic). No flags set => "",
// which contributes nothing to the briefing. The field must ALWAYS be present, though:
// the task's result templates {situational_directives}, and Node 1 throws a TEMPLATE
// ERROR on undefined ("" is fine).
return [{
    json: {
        ...input,
        PHASE_ID: "3",
        AGENT_ID: "scaffolding_manager",
        TASK_ID: "inject_constraints",
        situational_directives: directives.length
            ? "\n\n[SITUATIONAL DIRECTIVES]:\n" + directives.join("\n\n")
            : ""
    }
}];

// === 🐛 CFG INJECT EXECUTION ERROR ===
const inputData = items[0].json;

// 1. Extract the specific error
let errorText = "Unknown Error";
if (inputData.error) {
    if (inputData.error.message) {
        errorText = inputData.error.message;
    } else if (inputData.error.response && inputData.error.response.data) {
        const rawData = inputData.error.response.data;
        errorText = typeof rawData === 'object' ? JSON.stringify(rawData) : rawData.toString();
    }
}

// 2. Format the Multiline Context
const formattedError = `While attempting to execute python code:
*** PYTHON RUNTIME ERROR ***
The code crashed with this error:
${errorText}`;

// 3. Clean Payload (Remove raw error object)
const cleanData = { ...inputData };
delete cleanData.error; 

// 4. Set routing for the Global Error Injector
return [{
    json: {
        ...cleanData,
        PHASE_ID: "3",
        AGENT_ID: "review_manager",
        TASK_ID: "log_error",
        error_text: formattedError // The UA will swap this into $error_text
    }
}];

