const sel = $('Select Query').first().json;

const uuid = () =>
  (typeof crypto !== 'undefined' && crypto.randomUUID)
    ? crypto.randomUUID()
    : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
        const r = (Math.random() * 16) | 0;
        return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
      });

const raw = String(sel.query_index ?? '').trim();
const n = raw === '' ? 1 : Number(raw);

if (!Number.isInteger(n) || n < 1 || n > QUERIES.length) {
  throw new Error(
    `query_index must be a whole number from 1 to ${QUERIES.length}, got "${raw}".\n` +
    QUERIES.map((q, i) => `${i + 1}. ${q.split('\n')[0].slice(0, 70)}`).join('\n')
  );
}

const jobId = String(sel.job_id ?? '').trim() || uuid();
const style = String(sel.style_preference ?? '').trim() || 'casual_mobile';

console.log(`Query ${n}/${QUERIES.length} | job_id=${jobId}\n${QUERIES[n - 1].split('\n')[0]}`);

return [{
  json: {
    original_query: QUERIES[n - 1],
    job_id: jobId,
    style_preference: style,
